import React, { useState, useEffect } from "react";

function Home() {
  const [resumeText, setResumeText] = useState("");
  const [jobDesc, setJobDesc] = useState("");
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState(null);
  const [template, setTemplate] = useState("simple");
  const [matchData, setMatchData] = useState(null);
  const [photo, setPhoto] = useState(null);

  // ================= AUTH CHECK =================
  useEffect(() => {
    const token = localStorage.getItem("token");
    if (!token) window.location.href = "/login";
  }, []);

  // ================= OPTIMIZE =================
  const handleOptimize = async () => {
    if (!resumeText || !jobDesc) {
      alert("Fill all fields");
      return;
    }

    setLoading(true);

    try {
      const token = localStorage.getItem("token");

      const res = await fetch("http://localhost:5000/api/resume/optimize", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: token,
        },
        body: JSON.stringify({
          resumeText,
          jobDesc,
          template,
        }),
      });

      const data = await res.json();
      setResult(data);

    } catch (err) {
      console.log(err);
      alert("Error optimizing");
    } finally {
      setLoading(false);
    }
  };

  // ================= SAVE (FIXED ATS) =================
  const handleSave = async () => {
    try {
      const token = localStorage.getItem("token");

      if (!result || !result.optimizedText) {
        alert("Please optimize first");
        return;
      }

      const res = await fetch("http://localhost:5000/api/resume/save", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: token,
        },
        body: JSON.stringify({
          text: result.optimizedText,
          atsScore: result.score, // ✅ FIXED
        }),
      });

      await res.json();
      alert("Saved!");
    } catch (err) {
      console.log(err);
      alert("Save failed");
    }
  };

  // ================= JOB MATCH =================
  const handleMatch = async () => {
    try {
      const token = localStorage.getItem("token");

      if (!resumeText || !jobDesc) {
        alert("Fill resume + job description");
        return;
      }

      const res = await fetch("http://localhost:5000/api/resume/match", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: token,
        },
        body: JSON.stringify({ resumeText, jobDesc }),
      });

      const data = await res.json();
      setMatchData(data);

    } catch (err) {
      console.log(err);
      alert("Match error");
    }
  };

  // ================= PDF UPLOAD =================
  const handleFileUpload = async (e) => {
    const file = e.target.files[0];
    const token = localStorage.getItem("token");

    const formData = new FormData();
    formData.append("file", file);

    const res = await fetch("http://localhost:5000/api/resume/upload-pdf", {
      method: "POST",
      headers: { Authorization: token },
      body: formData,
    });

    const data = await res.json();
    setResumeText(data.text);
  };

  // ================= PHOTO UPLOAD =================
  const handlePhoto = (e) => {
    const reader = new FileReader();
    reader.onloadend = () => {
      setPhoto(reader.result.split(",")[1]);
    };
    reader.readAsDataURL(e.target.files[0]);
  };

  // ================= DOWNLOAD =================
  const handleDownload = async () => {
    const token = localStorage.getItem("token");

    const res = await fetch("http://localhost:5000/api/resume/download", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Authorization: token,
      },
      body: JSON.stringify({
        text: result.optimizedText,
        template,
        photo,
      }),
    });

    const blob = await res.blob();
    const url = window.URL.createObjectURL(blob);

    const a = document.createElement("a");
    a.href = url;
    a.download = "resume.pdf";
    a.click();
  };

  return (
    <div style={styles.page}>
      <h1 style={styles.logo}>CareerForge Pro 🚀</h1>

      <div style={styles.card}>

        <textarea
          placeholder="Paste Resume..."
          value={resumeText}
          onChange={(e) => setResumeText(e.target.value)}
          style={styles.textarea}
        />

        <textarea
          placeholder="Paste Job Description..."
          value={jobDesc}
          onChange={(e) => setJobDesc(e.target.value)}
          style={styles.textarea}
        />

        {/* PDF Upload */}
        <input type="file" onChange={handleFileUpload} />

        {/* Photo Upload */}
        <input type="file" onChange={handlePhoto} />

        <select
          value={template}
          onChange={(e) => setTemplate(e.target.value)}
          style={styles.select}
        >
          <option value="simple">Simple</option>
          <option value="modern">Modern</option>
          <option value="professional">Professional</option>
          <option value="minimal">Minimal</option>
        </select>

        <button style={styles.primaryBtn} onClick={handleOptimize}>
          {loading ? "Optimizing..." : "Optimize Resume"}
        </button>

        <button style={styles.secondaryBtn} onClick={handleMatch}>
          Check Job Match
        </button>

        <button
          style={styles.secondaryBtn}
          onClick={() => (window.location.href = "/dashboard")}
        >
          Go to Dashboard
        </button>
      </div>

      {/* RESULT */}
      {result && (
        <div style={styles.resultCard}>
          <h2>ATS Score: {result.score}</h2>

          <pre style={styles.output}>{result.optimizedText}</pre>

          <button style={styles.primaryBtn} onClick={handleSave}>
            Save Resume
          </button>

          <button style={styles.primaryBtn} onClick={handleDownload}>
            Download PDF
          </button>
        </div>
      )}

      {/* MATCH RESULT */}
      {matchData && (
        <div style={styles.resultCard}>
          <h2>Job Match Result</h2>

          <p>Score: {matchData.matchScore}</p>
          <p>Status: {matchData.message}</p>

          <h4>Roles:</h4>
          <ul>
            {matchData.roles.map((role, i) => (
              <li key={i}>{role}</li>
            ))}
          </ul>
        </div>
      )}
    </div>
  );
}

const styles = {
  page: {
    minHeight: "100vh",
    background: "linear-gradient(135deg,#020617,#0f172a)",
    padding: "30px",
    color: "white",
    textAlign: "center",
  },
  logo: {
    color: "#38bdf8",
  },
  card: {
    background: "rgba(255,255,255,0.05)",
    padding: "20px",
    borderRadius: "12px",
    width: "80%",
    margin: "auto",
    display: "flex",
    flexDirection: "column",
    gap: "10px",
  },
  textarea: {
    height: "120px",
    background: "#020617",
    color: "white",
    border: "1px solid #334155",
    padding: "10px",
    borderRadius: "8px",
  },
  select: {
    padding: "10px",
    borderRadius: "8px",
    background: "#020617",
    color: "white",
  },
  primaryBtn: {
    background: "#3b82f6",
    padding: "10px",
    border: "none",
    borderRadius: "8px",
    color: "white",
    cursor: "pointer",
  },
  secondaryBtn: {
    background: "#9333ea",
    padding: "10px",
    border: "none",
    borderRadius: "8px",
    color: "white",
    cursor: "pointer",
  },
  resultCard: {
    marginTop: "20px",
    padding: "20px",
    background: "rgba(255,255,255,0.05)",
    borderRadius: "12px",
    width: "80%",
    marginLeft: "auto",
    marginRight: "auto",
  },
  output: {
    background: "#020617",
    padding: "10px",
    borderRadius: "8px",
    textAlign: "left",
    whiteSpace: "pre-wrap",
  },
};

export default Home;
